import{_ as a,o as n,c as t,a3 as p}from"./chunks/framework.Dz5Q8p4s.js";const g=JSON.parse('{"title":"CALVIN: A Benchmark for Language-Conditioned Policy Learning for Long-Horizon Robot Manipulation Tasks","description":"","frontmatter":{"title":"CALVIN: A Benchmark for Language-Conditioned Policy Learning for Long-Horizon Robot Manipulation Tasks","arxiv":"2112.03227","date":"2021-12-06","authors":"Oier Mees, Lukas Hermann, Erick Rosete-Beas, Wolfram Burgard","categories":"cs.RO, cs.AI, cs.CL, cs.CV, cs.LG","topics":"具身智能评测, 语言条件操作, 长时程任务","outline":[2,2]},"headers":[],"relativePath":"papers/2112.03227.md","filePath":"papers/2112.03227.md","lastUpdated":null}'),l={name:"papers/2112.03227.md"};function e(i,s,r,m,o,c){return n(),t("div",null,[...s[0]||(s[0]=[p('<h1 id="calvin-a-benchmark-for-language-conditioned-policy-learning-for-long-horizon-robot-manipulation-tasks" tabindex="-1">CALVIN: A Benchmark for Language-Conditioned Policy Learning for Long-Horizon Robot Manipulation Tasks <a class="header-anchor" href="#calvin-a-benchmark-for-language-conditioned-policy-learning-for-long-horizon-robot-manipulation-tasks" aria-label="Permalink to &quot;CALVIN: A Benchmark for Language-Conditioned Policy Learning for Long-Horizon Robot Manipulation Tasks&quot;">​</a></h1><table tabindex="0"><thead><tr><th>项</th><th>内容</th></tr></thead><tbody><tr><td><strong>arXiv</strong></td><td><a href="https://arxiv.org/abs/2112.03227" target="_blank" rel="noreferrer">2112.03227</a></td></tr><tr><td><strong>提交日期</strong></td><td>2021-12-06</td></tr><tr><td><strong>作者</strong></td><td>Oier Mees, Lukas Hermann, Erick Rosete-Beas, Wolfram Burgard</td></tr><tr><td><strong>分类</strong></td><td>cs.RO, cs.AI, cs.CL, cs.CV, cs.LG</td></tr><tr><td><strong>一句话</strong></td><td>用 24 小时无脚本 play 数据配上只覆盖 1% 数据的语言标注，构造一个要求 7-DoF 闭环连续完成五条自由语言指令的操作基准，并用实验证明当时最强的模仿学习基线在五连链上只有 0.08% 成功率。</td></tr></tbody></table><blockquote><p><strong>所属教程</strong>：<a href="/notes/tutorials/video-for-embodied-ai">视频生成赋能具身智能</a></p></blockquote><h2 id="§-1-—-研究问题与重要性" tabindex="-1">§ 1 — 研究问题与重要性 <a class="header-anchor" href="#§-1-—-研究问题与重要性" aria-label="Permalink to &quot;§ 1 — 研究问题与重要性&quot;">​</a></h2><p>论文要解决的不是一个算法问题，而是一个<strong>评测缺口</strong>：2021 年时，&quot;用自由语言指挥机器人做连续多步操作&quot;这件事没有公开、可复现的评测台。当时的多任务学习普遍靠 goal image 或 one-hot 技能选择器指定任务，这两种接口对非专家用户都不可用。语言是唯一自然的接口，但语言驱动的连续控制策略当时只能在各家自建的私有环境里报数字，无法横向比较。CALVIN 的价值在于把四件事第一次同时钉在一个基准里：自由形式语言条件、多模态高维输入、7-DoF 连续控制、长时程物体操作。这个组合决定了后来一大批工作（包括本教程关心的&quot;用视频生成当策略&quot;路线）有了共同的坐标系。</p><h2 id="§-2-—-前人工作与不足" tabindex="-1">§ 2 — 前人工作与不足 <a class="header-anchor" href="#§-2-—-前人工作与不足" aria-label="Permalink to &quot;§ 2 — 前人工作与不足&quot;">​</a></h2><p>最接近的是 ALFRED：它有语言指令、有导航加操作，但动作空间是七个预定义的离散原语，智能体做的是分类而不是闭环连续控制。CALVIN 要求的是 30 Hz 连续动作输出，这把&quot;技能获取&quot;本身也纳入了问题范围。另一条线是 Lynch 等人的 learning-from-play 与 MCIL：它们已经证明了&quot;用无脚本 play 数据 + 少量事后语言标注&quot;能学出语言条件策略，CALVIN 的桌面环境正是照着它们设计以便公平对比。但作者点名了两个缺口：其一，MCIL 虽被视为 SOTA 却<strong>没有公开实现</strong>，导致无从复现；其二，原 MCIL 设定只有 18 个子任务、长时程链长 4、单一环境、单一传感器。CALVIN 把这些分别推到 34 个子任务、链长 5、四个环境、可组合的传感器套件，并新增了一个原设定没有的视觉 grounding 难点——不同颜色方块的指令措辞高度相似，智能体必须自己分辨说的是哪一块。</p><h2 id="§-3-—-重建作者的思考路径" tabindex="-1">§ 3 — 重建作者的思考路径 <a class="header-anchor" href="#§-3-—-重建作者的思考路径" aria-label="Permalink to &quot;§ 3 — 重建作者的思考路径&quot;">​</a></h2><p>出发点是一个已被 play 数据一系工作验证的观察：专家示教只展示一种解法，而无目的的自由探索数据覆盖了多模态解空间，还天然包含重试等次优行为，这些恰恰是鲁棒策略需要的。但 play 数据的天然形态是无分段的长流，没有任务标签。事后众包标注是可行的，可现实里不可能给所有交互配语言。于是就有了那个关键的工程折中：只标注 1% 的数据，其余靠 hindsight relabeling 从图像目标里学控制。接着要问&quot;怎么评&quot;。如果只测单条指令的成功率，模型可以靠初始状态与任务的相关性作弊；所以每条子任务之间要把机器人重置到中性位姿，切断初始状态与任务的关联，强迫策略只能从语言里读出该做什么。最后，要让长时程真的难，就需要&quot;上一条不成功不进入下一条&quot;的串行判定——这个判定又要求环境能自动检测任务完成，于是有了 34 条基于状态变化的成功判据（如&quot;方块横移超过 10 cm 且两帧都保持接触&quot;）。</p><h2 id="§-4-—-核心-intuition" tabindex="-1">§ 4 — 核心 Intuition <a class="header-anchor" href="#§-4-—-核心-intuition" aria-label="Permalink to &quot;§ 4 — 核心 Intuition&quot;">​</a></h2><p>把长时程能力测出来的办法不是把单个任务变难，而是把成功率<strong>串起来乘</strong>：五条指令必须依次成功，任何一步失败整条链就结束。同时用中性位姿重置切断&quot;看初始状态猜任务&quot;的捷径。这两条加起来，就把一个看似 50% 成功率的策略压到接近零，从而暴露出&quot;会做单步&quot;和&quot;会做序列&quot;之间的巨大鸿沟。</p><h2 id="§-5-—-具体方法与完整-pipeline" tabindex="-1">§ 5 — 具体方法与完整 Pipeline <a class="header-anchor" href="#§-5-—-具体方法与完整-pipeline" aria-label="Permalink to &quot;§ 5 — 具体方法与完整 Pipeline&quot;">​</a></h2><p>以评测中一条真实的链为例：<code>&quot;open drawer&quot; → &quot;push block in drawer&quot; → &quot;pick object from drawer&quot; → &quot;stack blocks&quot; → &quot;close drawer&quot;</code>。</p><ul><li><strong>环境</strong>：PyBullet 里四个结构相同、纹理与静态元件位置各异的桌面场景（A/B/C/D），配 7-DoF Franka Panda、滑门、抽屉、按钮、开关和三块彩色积木。</li><li><strong>观测</strong>：静态相机 RGB-D（<span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.7278em;vertical-align:-0.0833em;"></span><span class="mord">200</span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">×</span><span class="mspace" style="margin-right:0.2222em;"></span></span><span class="base"><span class="strut" style="height:0.6444em;"></span><span class="mord">200</span></span></span></span>）、腕部相机 RGB-D（<span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.7278em;vertical-align:-0.0833em;"></span><span class="mord">84</span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">×</span><span class="mspace" style="margin-right:0.2222em;"></span></span><span class="base"><span class="strut" style="height:0.6444em;"></span><span class="mord">84</span></span></span></span>）、视觉触觉图（<span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.7278em;vertical-align:-0.0833em;"></span><span class="mord">120</span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">×</span><span class="mspace" style="margin-right:0.2222em;"></span></span><span class="base"><span class="strut" style="height:0.7278em;vertical-align:-0.0833em;"></span><span class="mord">160</span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">×</span><span class="mspace" style="margin-right:0.2222em;"></span></span><span class="base"><span class="strut" style="height:0.6444em;"></span><span class="mord">2</span></span></span></span>）、本体感知（末端位姿、夹爪开度、7 个关节角）。动作空间可选绝对笛卡尔、相对笛卡尔或关节空间。</li><li><strong>数据</strong>：三位未受训的采集者在 VR 头显下每个环境各玩约 6 小时，共 24 小时、约 240 万交互步、约 4000 万条 1–2 秒的短时程窗口。</li><li><strong>语言</strong>：400 多条众包指令模板对应 34 个任务，用记录下来的环境状态<strong>程序化地</strong>贴到片段上，最终只有 1% 的交互数据带语言标注；另提供 MiniLM 抽的 384 维句向量。</li><li><strong>评测</strong>：MTLC 每个任务跑 10 次 rollout；LH-MTLC 用 1000 条经过去环、去冗余、去近似筛选的五连链，每条链之间重置到中性位姿，前一子任务由环境状态判定成功后才推进。</li><li><strong>难度档</strong>：训练/测试环境组合分 D→D（单环境）、A,B,C,D→D（多环境）、A,B,C→D（零样本未见环境）三档，再与传感器组合交叉。</li></ul><p>基线是 MCIL：一个 seq2seq CVAE，把无标注 play 数据 relabel 成图像目标条件的模仿学习，同时用 1% 的语言数据训练语言编码器，让两种目标共享同一个潜在 plan 空间与同一个策略解码器。</p><h2 id="§-6-—-核心数学推导" tabindex="-1">§ 6 — 核心数学推导 <a class="header-anchor" href="#§-6-—-核心数学推导" aria-label="Permalink to &quot;§ 6 — 核心数学推导&quot;">​</a></h2><p>基线只涉及一条标准的目标条件模仿学习目标。把 play 数据流 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6833em;"></span><span class="mord mathcal" style="margin-right:0.0278em;">D</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mopen">{(</span><span class="mord"><span class="mord mathnormal">x</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.2806em;"><span style="top:-2.55em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight">t</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mpunct">,</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord"><span class="mord mathnormal">a</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.2806em;"><span style="top:-2.55em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight">t</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mclose">)}</span></span></span></span> 做 hindsight relabeling，把任意访问过的状态 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.7167em;vertical-align:-0.2861em;"></span><span class="mord"><span class="mord mathnormal">x</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.1514em;"><span style="top:-2.55em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight" style="margin-right:0.0359em;">g</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.2861em;"><span></span></span></span></span></span></span></span></span></span> 当作&quot;已达成的目标&quot;，其之前的轨迹就是达成该目标的最优行为，于是得到</p><p class="katex-block"><span class="katex-display"><span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.9694em;vertical-align:-0.2861em;"></span><span class="mord"><span class="mord mathcal">L</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3361em;"><span style="top:-2.55em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mathnormal mtight">L</span><span class="mord mathnormal mtight" style="margin-right:0.1076em;">f</span><span class="mord mathnormal mtight" style="margin-right:0.1389em;">P</span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.2861em;"><span></span></span></span></span></span></span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:3.2281em;vertical-align:-1.2671em;"></span><span class="mord"><span class="mord mathbb">E</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3448em;"><span style="top:-2.5198em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mopen mtight">(</span><span class="mord mathnormal mtight" style="margin-right:0.1132em;">τ</span><span class="mpunct mtight">,</span><span class="mord mtight"><span class="mord mathnormal mtight">x</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.1645em;"><span style="top:-2.357em;margin-left:0em;margin-right:0.0714em;"><span class="pstrut" style="height:2.5em;"></span><span class="sizing reset-size3 size1 mtight"><span class="mord mathnormal mtight" style="margin-right:0.0359em;">g</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.2819em;"><span></span></span></span></span></span></span><span class="mclose mtight">)</span><span class="mrel mtight">∼</span><span class="mord mtight"><span class="mord mathnormal mtight" style="margin-right:0.0278em;">D</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3448em;"><span style="top:-2.3488em;margin-left:-0.0278em;margin-right:0.0714em;"><span class="pstrut" style="height:2.5em;"></span><span class="sizing reset-size3 size1 mtight"><span class="mord text mtight"><span class="mord mtight">play</span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.2901em;"><span></span></span></span></span></span></span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.3833em;"><span></span></span></span></span></span></span><span class="mord"><span class="delimsizing size2">[</span></span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mop op-limits"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:1.961em;"><span style="top:-1.8829em;margin-left:0em;"><span class="pstrut" style="height:3.05em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mathnormal mtight">t</span><span class="mrel mtight">=</span><span class="mord mtight">0</span></span></span></span><span style="top:-3.05em;"><span class="pstrut" style="height:3.05em;"></span><span><span class="mop op-symbol large-op">∑</span></span></span><span style="top:-4.386em;margin-left:0em;"><span class="pstrut" style="height:3.05em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mtight">∣</span><span class="mord mathnormal mtight" style="margin-right:0.1132em;">τ</span><span class="mord mtight">∣</span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:1.2671em;"><span></span></span></span></span></span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mop">lo<span style="margin-right:0.0139em;">g</span></span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.0359em;">π</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3361em;"><span style="top:-2.55em;margin-left:-0.0359em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight" style="margin-right:0.0278em;">θ</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mopen">(</span><span class="mord"><span class="mord mathnormal">a</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.2806em;"><span style="top:-2.55em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight">t</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">∣</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:1.8em;vertical-align:-0.65em;"></span><span class="mord"><span class="mord mathnormal">x</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.2806em;"><span style="top:-2.55em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight">t</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mpunct">,</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord"><span class="mord mathnormal">x</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.1514em;"><span style="top:-2.55em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight" style="margin-right:0.0359em;">g</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.2861em;"><span></span></span></span></span></span></span><span class="mclose">)</span><span class="mord"><span class="delimsizing size2">]</span></span><span class="mord">.</span></span></span></span></span></p><p>这个式子的直觉是&quot;事后诸葛亮&quot;：任何一段轨迹，只要把它的终点宣布为目标，它就自动变成一条成功示范，因此无脚本数据可以零成本地转成监督信号。多上下文（multi-context）这一步的作用是让 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.0359em;">π</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3361em;"><span style="top:-2.55em;margin-left:-0.0359em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight" style="margin-right:0.0278em;">θ</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mopen">(</span><span class="mord"><span class="mord mathnormal">a</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.2806em;"><span style="top:-2.55em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight">t</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">∣</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mord"><span class="mord mathnormal">x</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.2806em;"><span style="top:-2.55em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight">t</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mpunct">,</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord mathnormal" style="margin-right:0.044em;">z</span><span class="mclose">)</span></span></span></span> 只依赖一个潜在 plan <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.4306em;"></span><span class="mord mathnormal" style="margin-right:0.044em;">z</span></span></span></span>，而 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.4306em;"></span><span class="mord mathnormal" style="margin-right:0.044em;">z</span></span></span></span> 既可以由图像目标编码器产生、也可以由语言编码器产生——这就是&quot;语言标注只需 1%&quot;的形式依据：控制主要从图像目标里学，语言只负责把自己映射到已有的 plan 空间。CVAE 的 KL 项权重取 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.8889em;vertical-align:-0.1944em;"></span><span class="mord mathnormal" style="margin-right:0.0528em;">β</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:0.6444em;"></span><span class="mord">0.001</span></span></span></span>。</p><h2 id="§-7-—-实验设计与结论" tabindex="-1">§ 7 — 实验设计与结论 <a class="header-anchor" href="#§-7-—-实验设计与结论" aria-label="Permalink to &quot;§ 7 — 实验设计与结论&quot;">​</a></h2><p>问题一：单步语言条件控制到底做到什么水平？只用静态相机 RGB、同环境训练测试时，34 个任务的 MTLC 成功率是 53.9%。加腕部相机（51.8%）、加深度（46.1%）、加触觉（54.2%）都没有带来实质提升。作者的假设是腕部相机需要配相对动作而不是绝对动作才能发挥作用，且未做图像增广。定性分析还发现性能显著依赖机器人初始位姿，暗示策略在利用上下文而非真正解耦初始状态与任务。</p><p>问题二：长时程呢？同一行配置下，五连链的第一步成功率 48.9%，随后是 12.9%、2.6%、0.5%，第五步 0.08%。这是全文最有信息量的一组数字：单步 50% 级的策略在链长 5 上几乎归零。作者还观察到策略常常正确执行了积木操作但<strong>弄错了颜色</strong>，并把原因归给语言编码——MiniLM 对含 &quot;red&quot; 与含 &quot;blue&quot; 的句子给出相近的嵌入。</p><p>问题三：换环境还能用吗？多环境（A,B,C,D→D）与零样本（A,B,C→D）两档全面下滑，零样本档下静态相机的链长 3 成功率只有 0.2%，链长 4 起全为 0。这里有一处值得指出的非单调：静态 RGB 那一行里，零样本 A,B,C→D 的 MTLC 是 38.6%，反而<strong>高于</strong>多环境 A,B,C,D→D 的 35.6%；其余三组传感器配置都是单调的。论文没有讨论这一反常，按常理&quot;见过测试环境&quot;不应该更差，可以推断这一档的方差不小（每任务仅 10 次 rollout）。</p><p>结论是自证式的：作者的目的就是证明这个基准还没被解决，从而说明它值得存在。</p><h2 id="§-8-—-take-aways" tabindex="-1">§ 8 — Take-aways <a class="header-anchor" href="#§-8-—-take-aways" aria-label="Permalink to &quot;§ 8 — Take-aways&quot;">​</a></h2><p><strong>5 句话版</strong>：CALVIN 把自由语言、多模态感知、7-DoF 连续控制和长时程操作第一次装进同一个公开基准。数据是 24 小时无脚本 play，语言标注只覆盖 1%，靠 hindsight relabeling 把无标注部分转成监督信号。评测的核心设计是五连指令串行判定加中性位姿重置，前者让成功率相乘，后者切断&quot;看初始状态猜任务&quot;的捷径。四个纹理与布局各异的环境支持单环境、多环境、零样本三档难度。MCIL 基线单步 53.9%、五连 0.08%，说明&quot;会做单步&quot;离&quot;会做序列&quot;极远。</p><p><strong>3 句话版</strong>：语言条件操作缺一个公开可比的长时程基准，CALVIN 补上了。它用 play 数据加 1% 语言标注做训练集，用五连指令串行判定做评测。SOTA 基线在五连上只有 0.08%，缺口由此被量化。</p><p><strong>1 句话版</strong>：一个把&quot;长时程&quot;真正测出来的语言条件操作基准，代价是让当时最好的方法几乎交白卷。</p><h2 id="§-9-—-最脆弱的假设" tabindex="-1">§ 9 — 最脆弱的假设 <a class="header-anchor" href="#§-9-—-最脆弱的假设" aria-label="Permalink to &quot;§ 9 — 最脆弱的假设&quot;">​</a></h2><p>最要害的一条是：<strong>CALVIN 的成功判据能否代表&quot;完成了人说的那件事&quot;</strong>。34 个任务的判定全部写成环境状态的阈值变化——旋转超过 60°、横移超过 10 cm、抬高超过 5 cm、滑门推开至少 12 cm。这套判据让自动标注和自动评测成为可能，是整个基准得以规模化的前提；但它也意味着任何满足阈值的运动都算成功，无论过程是否是人类意义上的&quot;把方块推到左边&quot;。风险在长时程链上被放大：链式判定只看每一步的终态，于是一个策略完全可以用不自然但恰好越过阈值的动作刷过前几步。论文为这一假设提供的证据是间接的——它展示了判据可以用于离线数据的自动打标，但没有做人工核验去测量&quot;判据判成功&quot;与&quot;人判成功&quot;的一致率。如果两者差距大，那么 CALVIN 上的排行榜衡量的就是&quot;越阈值的效率&quot;而非语言 grounding 能力。反过来看，这个假设的脆弱性也解释了后来社区为什么会同时使用 <a href="/notes/papers/2306.03310">LIBERO</a> 这类带更细任务族划分的基准来交叉验证。</p><h2 id="§-10-—-最小复现实验" tabindex="-1">§ 10 — 最小复现实验 <a class="header-anchor" href="#§-10-—-最小复现实验" aria-label="Permalink to &quot;§ 10 — 最小复现实验&quot;">​</a></h2><p>不需要训练任何策略。用官方发布的数据与环境做一次<strong>判据审计</strong>：从 play 数据里按环境状态自动检出每类任务的若干片段，随机抽 200 段（覆盖 34 类），请 3 个人独立判断&quot;这段视频是否完成了对应的语言指令&quot;，计算人机一致率与 Krippendorff <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.4306em;"></span><span class="mord mathnormal" style="margin-right:0.0037em;">α</span></span></span></span>。同时构造一组对抗片段：用脚本生成刚好越过阈值但过程明显异常的轨迹（例如把方块拨飞后落点恰好右移超过 10 cm），看判据是否照样判成功。判据一致率高于 0.9 且对抗片段大多被拒，支持 §9 的假设；若一致率低于 0.8 或对抗片段大面积通过，那么基于 CALVIN 的绝对成功率数字需要重新解释。这个实验一周内可完成，且完全不依赖复现 MCIL。</p><h2 id="§-11-—-最强反例设计" tabindex="-1">§ 11 — 最强反例设计 <a class="header-anchor" href="#§-11-—-最强反例设计" aria-label="Permalink to &quot;§ 11 — 最强反例设计&quot;">​</a></h2><p>针对论文的核心 claim&quot;CALVIN 的长时程任务很难&quot;，最有力的替代解释是：<strong>0.08% 主要反映了基线的语言编码有缺陷，而不是长时程本身难</strong>。证据就在论文自己的文字里——策略&quot;常常正确执行了积木操作但弄错颜色&quot;，原因归给 MiniLM 对 red/blue 句子嵌入过近。如果颜色混淆是主要失败模式，那么每一步都有约 1/3 的机会选错积木，五步连乘自然趋近于零，而这与&quot;长时程规划难&quot;无关。设计的反例实验是：把语言条件换成<strong>oracle 的离散任务 ID</strong>（34 选一，完全消除语言歧义），其余全部不变，重跑 LH-MTLC。若五连成功率从 0.08% 跳到个位数百分比以上，说明基准当时测出来的主要是语言 grounding 而非长时程；若仍然接近零，论文的结论就被加固。第二个攻击面是评测方差：每任务 10 次 rollout、五连链 1000 条，而链长 4、5 的成功率已经落在 0–0.5% 区间，单次成败就能改变第三位有效数字，论文没有报任何置信区间或多种子重复。</p><h2 id="§-12-—-follow-up-research-idea" tabindex="-1">§ 12 — Follow-up Research Idea <a class="header-anchor" href="#§-12-—-follow-up-research-idea" aria-label="Permalink to &quot;§ 12 — Follow-up Research Idea&quot;">​</a></h2><p>CALVIN 把长时程建模成&quot;五条<strong>独立</strong>指令的串行执行&quot;，每步之间重置到中性位姿、每步单独判定。这个 framing 让评测干净，但也切断了真正的长时程结构：真实任务里后一步的可行性依赖前一步留下的世界状态，而且人不会把每一步都说出来。一个非增量的重构是把基准从&quot;指令序列&quot;改成&quot;<strong>单条欠定指令 + 状态依赖的完成判据</strong>&quot;，例如只说&quot;把桌面收拾干净&quot;，由环境根据终态是否满足一组约束来判定，中间不给任何子指令。可借鉴的相邻领域工具是形式化验证里的时序逻辑规约（LTL / signal temporal logic）：用它把&quot;收拾干净&quot;写成一组必须在时间上依次满足的谓词，既保留自动判定的可行性，又不再要求把解法预先分解成固定的五步。第一个实验可以直接在现有 CALVIN 环境里做：取现有 1000 条链，把每条链的终态约束合取成一条 LTL 公式，只把公式对应的一句自然语言描述给策略，比较同一策略在&quot;五条指令逐条给&quot;与&quot;一句总目标&quot;两种条件下的完成率。两者差距的大小，直接量化了当前语言条件策略里有多少能力其实来自人类替它做好的任务分解。</p>',36)])])}const u=a(l,[["render",e]]);export{g as __pageData,u as default};
